{
    var memberId = Convert.ToInt32(newJob.MemberId);
    var member = _context.Members.FirstOrDefault(m => m.Id == memberId);

    var offsetTimespan = member.TimezoneOffsetMinutes.HasValue
        ? TimeSpan.FromMinutes(member.TimezoneOffsetMinutes.Value)
        : Constants.DefaultTimezoneOffset;

    var dayBegin = Constants.WorkdayBeginUtc - offsetTimespan;
    var dayEnd = Constants.WorkdayEndUtc - offsetTimespan;

    var jobs = _context.Jobs
        .Where(j => j.MemberId == newJob.MemberId)
        .Where(j => j.start.HasValue && j.end.HasValue)
        .Where(j => !j.Finished.HasValue || !j.Finished.Value)
        .OrderBy(j => j.start)
        .ToList();


    var startDate = finishedJob.ActualEnd ?? DateTime.Now;
    newJob.Deadline = CalculateDeadlineDate(startDate, nextStage.Deadline.Value, nextStage.DeadlineUnit, offsetTimespan);

    while (true)
    {
        var endDate = startDate + TimeSpan.FromMinutes(nextStage.DurationMinutes.Value);
        var overlappingJobs = jobs.Where(j => j.start <= endDate && j.end >= startDate).ToList();
        if (!overlappingJobs.Any() && endDate.TimeOfDay < dayEnd)
        {
            newJob.start = startDate;
            newJob.end = endDate;
            return;
        }

        if (overlappingJobs.Any())
        {
            startDate = overlappingJobs.Select(j => j.end).Max().Value;
        }
        else
        {
            startDate = startDate.AddBusinessDays(1).Date + dayBegin;
        }

    }


}

{
    var newJob = new Job();

    newJob.LoopId = finishedJob.LoopId;
    newJob.MainUserId = finishedJob.MainUserId;
    newJob.ParentId = finishedJob.ParentId;

    var finishedStage = _context.Stages.FirstOrDefault(s => s.Id == finishedJob.StageId);
    if (finishedStage == null)
    {
        return null;
    }

    var nextStage = _context.Stages
        .Where(s => s.LoopId == finishedStage.LoopId)
        .Where(s => s.SortOrder > finishedStage.SortOrder)
        .Include(s => s.Member)
        .Include(s => s.Filial)
        .OrderBy(s => s.SortOrder)
        .ThenBy(s => s.Id)
        .FirstOrDefault();

    if (nextStage == null)
    {
        //could not locate next stage - can't create new job
        return null;
    }

    if (nextStage.Member == null && nextStage.Filial == null)
    {
        //no member or team specified - can't assing new job to anyone
        return null;
    }

    if (nextStage.Deadline == null || string.IsNullOrEmpty(nextStage.DeadlineUnit))
    {
        //can't determine new job length
        return null;
    }

    if (!nextStage.DurationMinutes.HasValue || TimeSpan.FromMinutes(nextStage.DurationMinutes.Value) > TimeSpan.FromHours(8))
    {
        //too long stage can't be scheduled automatically
        return null;
    }

    newJob.StageId = nextStage.Id;

    if (nextStage.Member != null)
    {
        newJob.MemberId = nextStage.Member.Id.ToString();
    }
    else if (nextStage.Filial != null)
    {
        var member = SelectMember(nextStage.Filial, newJob.start.Value, newJob.end.Value);
        newJob.MemberId = member.Id.ToString();
    }

    SetDates(newJob, nextStage, finishedJob);
    SetTitle(newJob);



    return newJob;
}

